 p=metric(name,'primary');f=p['feature_known_n'];lines.append(f"| {name} | {v['n']} | {p['eligible_known_human_n']} | {v['native_available_n']} | {f['a']} | {f['b']} | {f['c']} | {v['render_actual_available_n']} | {v['prediction_group_n']} |")
